def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    import os
    import subprocess

    if os.name != 'nt':
        return cmd

    if not cmd:
        return cmd

    script = cmd[0]
    try:
        with open(script, 'r', encoding='utf-8') as f:
            first_line = f.readline().strip()
    except (OSError, UnicodeDecodeError):
        return cmd

    if not first_line.startswith('#!'):
        return cmd

    shebang = first_line[2:].strip()
    if not shebang:
        return cmd

    shebang_parts = shebang.split()
    interpreter = shebang_parts[0]
    if not os.path.isabs(interpreter):
        interpreter = subprocess.check_output(['where', interpreter], text=True).strip().split('\n')[0]

    shebang_args = shebang_parts[1:] if len(shebang_parts) > 1 else []
    new_cmd = [interpreter] + shebang_args + list(cmd[1:])
    return tuple(new_cmd)

