def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """
    if not orderings:
        return []

    # Create a graph where each node points to its successors
    graph = {}
    for ordering in orderings:
        for i in range(len(ordering)):
            if ordering[i] not in graph:
                graph[ordering[i]] = set()
            if i + 1 < len(ordering):
                graph[ordering[i]].add(ordering[i + 1])

    # Find all nodes with no predecessors
    indegree = {node: 0 for node in graph}
    for node in graph:
        for neighbor in graph[node]:
            indegree[neighbor] += 1

    # Perform a topological sort using Kahn's algorithm
    result = []
    queue = [node for node in indegree if indegree[node] == 0]

    while queue:
        current = queue.pop(0)
        result.append(current)
        for neighbor in graph[current]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                queue.append(neighbor)

    # Check if we have all the elements in the result
    all_elements = set()
    for ordering in orderings:
        all_elements.update(ordering)

    if len(result) != len(all_elements):
        raise ValueError("Orderings cannot be merged due to conflicting constraints")

    return result

