    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _legacy_mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """
    from collections import defaultdict

    # Create a graph where each node points to its next nodes
    graph = defaultdict(list)
    # Create a set to keep track of all nodes
    all_nodes = set()

    # Build the graph from the orderings
    for ordering in orderings:
        all_nodes.update(ordering)
        for i in range(len(ordering) - 1):
            graph[ordering[i]].append(ordering[i + 1])

    # Function to perform topological sorting (Kahn's algorithm)
    def topological_sort(graph, all_nodes):
        in_degree = {u: 0 for u in all_nodes}
        zero_in_degree = []

        # Calculate in-degrees for each node
        for u in graph:
            for v in graph[u]:
                in_degree[v] += 1

        # Collect nodes with no incoming edges
        for u in in_degree:
            if in_degree[u] == 0:
                zero_in_degree.append(u)

        result = []
        while zero_in_degree:
            u = zero_in_degree.pop(0)
            result.append(u)
            for v in graph[u]:
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    zero_in_degree.append(v)

        # If the result contains all nodes, return it
        if len(result) == len(all_nodes):
            return result
        else:
            raise ValueError("Graph has a cycle or is not fully connected.")

    try:
        return topological_sort(graph, all_nodes)
    except ValueError as e:
        raise ValueError("Orderings are invalid or contain cycles.") from e

