                seen.difference_update({seen_cls for seen_cls in seen if issubclass(cls, seen_cls)})

        # Return the result in the correct order
        return list(reversed(result))
    except Exception as e:
        # Handle any exceptions that occur during the process
        raise ValueError("Error in minimalBases: " + str(e))

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    minimal = []
    for cls in classes:
        if not any(issubclass(c, cls) for c in classes if c is not cls):
            minimal.append(cls)
    return minimal

