def format(
		self,
		sql: AnyStr,
		params: Union[Dict[Union[str, int], Any], Sequence[Any]],
	) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
		"""
		Convert the SQL query to use the out-style parameters instead of
		the in-style parameters.

		*sql* (:class:`str` or :class:`bytes`) is the SQL query.

		*params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
		contains the set of in-style parameters. It maps each parameter
		(:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
		is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
		If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
		*params* must be a :class:`~collections.abc.Sequence`.

		Returns a :class:`tuple` containing:

		-	The formatted SQL query (:class:`str` or :class:`bytes`).

		-	The set of converted out-style parameters (:class:`dict` or
			:class:`list`).
		"""
		try:
			if self.SQLParams.in_style in ['named', 'pyformat']:
				if not isinstance(params, collections.abc.Mapping):
					raise ValueError("For named or pyformat styles, params must be a mapping.")
				out_params = {str(k): v for k, v in params.items()}
				in_param_format = self.SQLParams.in_style_map.get(self.SQLParams.in_style)
				out_param_format = self.SQLParams.out_style_map.get(self.SQLParams.out_style)
				for param, value in out_params.items():
					sql = sql.replace(in_param_format % param, out_param_format % param)
			elif self.SQLParams.in_style in ['qmark', 'numeric', 'format', 'percent']:
				if not isinstance(params, collections.abc.Sequence):
					raise ValueError("For qmark, numeric, format, or percent styles, params must be a sequence.")
				out_params = list(params)
				if self.SQLParams.in_style == 'qmark':
					in_param_marker = '?'
				elif self.SQLParams.in_style == 'numeric':
					in_param_marker = ':'
				elif self.SQLParams.in_style == 'format':
					in_param_marker = '%s'
				elif self.SQLParams.in_style == 'percent':
					in_param_marker = '%'
				out_param_marker = self.SQLParams.out_style_map.get(self.SQLParams.out_style)
				param_count = sql.count(in_param_marker)
				if param_count != len(out_params):
					raise ValueError(f"In-style parameter count ({param_count}) does not match the number of provided parameters ({len(out_params)}).")
				for _ in range(param_count):
					sql = sql.replace(in_param_marker, out_param_marker, 1)
			else:
				raise ValueError(f"Unsupported in-style parameter type: {self.SQLParams.in_style}")
			return sql, out_params
		except Exception as e:
			raise ValueError(f"Error formatting SQL: {str(e)}")

def format(
    self,
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
    contains the set of in-style parameters. It maps each parameter
    (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
    is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
    If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
    *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -	The formatted SQL query (:class:`str` or :class:`bytes`).

    -	The set of converted out-style parameters (:class:`dict` or
            :class:`list`).
    """
    try:
        if self.SQLParams.in_style == 'named':
            if not isinstance(params, Mapping):
                raise ValueError("For named parameter style, params must be a Mapping.")
            out_params = {k: params[k] for k in params}
            for key in out_params:
                sql = sql.replace(f":{key}", f"@{key}")
        elif self.SQLParams.in_style in ['qmark', 'numeric', 'named', 'format', 'pyformat']:
            if not isinstance(params, Sequence):
                raise ValueError("For ordinal parameter style, params must be a Sequence.")
            out_params = list(params)
            if self.SQLParams.in_style == 'qmark':
                sql = sql.replace('?', '@p1')
                for i in range(1, len(out_params)):
                    sql = sql.replace('?', f'@p{i+1}')
            elif self.SQLParams.in_style == 'numeric':
                for i, _ in enumerate(out_params):
                    sql = sql.replace(f":{i+1}", f"@p{i+1}")
            elif self.SQLParams.in_style == 'format':
                sql = sql % tuple(f"@p{i+1}" for i in range(len(out_params)))
            elif self.SQLParams.in_style == 'pyformat':
                for i in range(len(out_params)):
                    sql = sql.replace(f"%({i+1})s", f"@p{i+1}")
        else:
            raise ValueError(f"Unsupported parameter style: {self.SQLParams.in_style}")
        return sql, out_params
    except Exception as e:
        raise ValueError(f"Error formatting SQL query: {e}")

