    package_data = {}

    try:
        if not os.path.isdir(folder):
            raise ValueError(f"The provided path {folder} is not a directory.")

        for filename in os.listdir(folder):
            if filename.endswith('.xml'):
                base_name = os.path.splitext(filename)[0]
                if base_name not in package_data:
                    package_data[base_name] = []
                package_data[base_name].append(os.path.join(folder, filename))

    except Exception as e:
        print(f"An error occurred: {e}")

    return package_data

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os
    import xml.etree.ElementTree as ET

    package_data = {}

    try:
        for filename in os.listdir(folder):
            if filename.endswith('.xml'):
                filepath = os.path.join(folder, filename)
                tree = ET.parse(filepath)
                root = tree.getroot()
                base_name = os.path.splitext(filename)[0]
                if base_name not in package_data:
                    package_data[base_name] = []
                package_data[base_name].append({
                    'filename': filename,
                    ' filepath': filepath,
                    'root': root
                })
    except FileNotFoundError:
        raise ValueError(f"The folder {folder} does not exist.")
    except ET.ParseError:
        raise ValueError(f"Error parsing XML file in {folder}.")
    except Exception as e:
        raise Exception(f"An unexpected error occurred: {e}")

    return package_data

