def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import zipfile
    import os

    result = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zip_ref:
            for file_info in zip_ref.infolist():
                if file_info.filename.endswith('.xml'):
                    base_name = os.path.basename(file_info.filename)
                    with zip_ref.open(file_info) as file:
                        if base_name in result:
                            result[base_name].append(file.read())
                        else:
                            result[base_name] = [file.read()]
    except FileNotFoundError:
        raise FileNotFoundError(f"The file at {zip_path} was not found.")
    except zipfile.BadZipFile:
        raise ValueError(f"The file at {zip_path} is not a valid zip file.")
    except Exception as e:
        raise Exception(f"An error occurred while processing the zip file at {zip_path}: {e}")

    return result

