def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    indent_str = "  " * indent
    representation = f"{indent_str}<{self.__class__.__name__}>"
    if debug:
        representation += f" id={getattr(self, 'id', 'None')}"
    for key, value in vars(self).items():
        if not key.startswith('_'):
            if hasattr(value, 'pretty'):
                representation += f"\n{value.pretty(indent+1)}"
            else:
                representation += f"\n{indent_str}  {key}: {value}"
    return representation

def pretty(self, indent=0, debug=False):
