    try:
        indent_str = '  ' * indent
        output = indent_str + repr(self) + '\n'
        for attr in dir(self):
            if not attr.startswith('__') and not callable(getattr(self, attr)):
                value = getattr(self, attr)
                if debug or not isinstance(value, (list, dict, set)):
                    output += (indent_str + '  ' + str(attr) + ': ' + repr(value) + '\n')
                else:
                    output += (indent_str + '  ' + str(attr) + ': ' + str(type(value)) + '\n')
        return output
    except Exception as e:
        return indent_str + "Error pretty printing object: " + str(e) + '\n'

