    """
    indent_str = '  ' * indent
    pretty_representation = f"{indent_str}{self.__class__.__name__}(\n"
    for attr, value in self.__dict__.items():
        if isinstance(value, list):
            pretty_representation += f"{indent_str}  {attr}=[\n"
            for item in value:
                if hasattr(item, 'pretty'):
                    pretty_representation += f"{item.pretty(indent + 2, debug)},\n"
                else:
                    pretty_representation += f"{'  ' * (indent + 2)}{item},\n"
            pretty_representation += f"{indent_str}  ],\n"
        elif hasattr(value, 'pretty'):
            pretty_representation += f"{indent_str}  {attr}={value.pretty(indent + 1, debug)},\n"
        else:
            pretty_representation += f"{indent_str}  {attr}={value},\n"
    pretty_representation += f"{indent_str})"
    return pretty_representation

