def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    try:
        new_args = []
        for expr in args:
            if isinstance(expr, tuple) and len(expr) == 3:
                op, left, right = expr
                if op == '&':
                    if right == ( '|', left, right[2] ):
                        new_args.append(left)
                    elif right == ( '&', ( '~', left ), right[2] ):
                        new_args.append( ( '&', left, right[2] ) )
                    else:
                        new_args.append(expr)
                elif op == '|':
                    if right == ( '&', left, right[2] ):
                        new_args.append(left)
                    elif right == ( '|', ( '~', left ), right[2] ):
                        new_args.append( ( '|', left, right[2] ) )
                    else:
                        new_args.append(expr)
                else:
                    new_args.append(expr)
            else:
                new_args.append(expr)
        return new_args
    except Exception as e:
        raise ValueError(f"Error processing expression: {e}")

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    import copy
    from collections import deque

    def apply_absorption(expr):
        if not isinstance(expr, (tuple, list)) or len(expr) != 3:
            return expr
        op = expr[0]
        if op in ('&', '|'):
            left, right = expr[1], expr[2]
            if isinstance(left, (tuple, list)) and len(left) == 3:
                op_left = left[0]
                left_left, left_right = left[1], left[2]
                if op == op_left and right == left_left:
                    return left
                elif op == op_left and right == left_right:
                    return left
                elif op == '&' and op_left == '|' and right[0] == '~' and right[1] == left_left:
                    return apply_absorption(('&', left_left, left_right))
                elif op == '&' and op_left == '|' and right[0] == '~' and right[1] == left_right:
                    return apply_absorption(('&', left_left, left_right))
                elif op == '|' and op_left == '&' and right[0] == '~' and right[1] == left_left:
                    return apply_absorption(('|', left_left, left_right))
                elif op == '|' and op_left == '&' and right[0] == '~' and right[1] == left_right:
                    return apply_absorption(('|', left_left, left_right))
        return expr

    new_args = deque(args)
    processed_args = []
    while new_args:
        current_expr = new_args.popleft()
        if isinstance(current_expr, (tuple, list)):
            if current_expr[0] in ('&', '|'):
                new_expr = apply_absorption(current_expr)
                if new_expr != current_expr:
                    new_args.extendleft(reversed(new_expr[1:]))
                else:
                    processed_args.append(new_expr)
            else:
                processed_args.append(current_expr)
        else:
            processed_args.append(current_expr)
    return processed_args

def absorb(self, args):
    """Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    from collections import deque

    def apply_absorption(expr1, expr2):
        if expr1 == ('&', expr2[0], expr2[1]) and expr2[1] == ('|', expr2[0], '_'):
            return expr2[0]
        if expr1 == ('|', expr2[0], expr2[1]) and expr2[1] == ('&', expr2[0], '_'):
            return expr2[0]
        if expr1 == ('&', expr2[0], expr2[1]) and expr2[1] == ('|', ('~', expr2[0]), '_'):
            return ('&', expr2[0], expr2[1][1])
        if expr1 == ('|', expr2[0], expr2[1]) and expr2[1] == ('&', ('~', expr2[0]), '_'):
            return ('|', expr2[0], expr2[1][1])
        return None

    queue = deque(args)
    processed = set()
    absorbed_args = []

    while queue:
        expr1 = queue.popleft()
        if expr1 in processed:
            continue
        processed.add(expr1)
        absorbed_expr = None

        for expr2 in list(queue):
            absorbed_expr = apply_absorption(expr1, expr2)
            if absorbed_expr:
                queue.remove(expr2)
                break

        if absorbed_expr:
            absorbed_args.append(absorbed_expr)
        else:
            absorbed_args.append(expr1)

    return absorbed_args

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.

    """
    def decorator(func):
        if not hasattr(self, '_handlers'):
            self._handlers = {}
        if hook not in self._handlers:
            self._handlers[hook] = []
        self._handlers[hook].append(func)
        return func
    return decorator

