def normalized(self):
    """
    Return a version of this object represented entirely using integer
    values for the relative attributes.

    >>> relativedelta(days=1.5, hours=2).normalized()
    relativedelta(days=+1, hours=+14)

    :return:
        Returns a :class:`dateutil.relativedelta.relativedelta` object.
    """
    try:
        normalized = relativedelta()
        for attribute in self._fields:
            value = getattr(self, attribute)
            if isinstance(value, float):
                # Convert float to int and distribute the remainder to the next smaller unit
                int_value = int(value)
                remainder = value - int_value
                setattr(normalized, attribute, int_value)
                if attribute == 'days':
                    normalized.hours += int(remainder * 24)
                elif attribute == 'hours':
                    normalized.minutes += int(remainder * 60)
                elif attribute == 'minutes':
                    normalized.seconds += int(remainder * 60)
                elif attribute == 'seconds':
                    normalized.microseconds += int(remainder * 1_000_000)
            else:
                setattr(normalized, attribute, value)
        return normalized
    except Exception as e:
        raise ValueError(f"Error normalizing relativedelta: {e}")

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def wrapper(*args, **kwargs):
        result = namefunc(*args, **kwargs)
        try:
            # Convert each element to a bytestring if it's a unicode string
            return tuple(s.encode('utf-8') if isinstance(s, unicode) else s for s in result)
        except NameError:
            # Python 3 does not have 'unicode' type, so we return the result as is
            return result
    return wrapper

