def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import os

    if not isinstance(commands, list) or not commands:
        raise ValueError("Commands must be a non-empty list.")
    if not isinstance(args, list):
        raise ValueError("Arguments must be a list.")
    if cwd and not os.path.isdir(cwd):
        raise ValueError("Current working directory is not valid.")

    full_command = commands + args
    if verbose:
        print("Running:", ' '.join(full_command))

    try:
        with subprocess.Popen(full_command, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE if hide_stderr else subprocess.STDOUT) as process:
            output, _ = process.communicate()
            if process.returncode != 0:
                raise subprocess.CalledProcessError(process.returncode, full_command, output=output)
    except Exception as e:
        if verbose:
            print("Error:", str(e))
        raise

    if verbose:
        print("Output:", output.decode('utf-8'))

    return output.decode('utf-8')

