def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    try:
        parts = version.split('.')
        last_part = str(int(parts[-1]) + 1)
        # Preserve leading zeros in the last part if they were present
        if parts[-1].startswith('0') and len(parts[-1]) > 1:
            last_part = last_part.zfill(len(parts[-1]))
        parts[-1] = last_part
        return '.'.join(parts)
    except (ValueError, IndexError):
        raise ValueError("Invalid version format")

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    if not isinstance(version_dirs, list):
        raise ValueError("version_dirs must be a list of directory names.")

    root_inventory = self.get_root_inventory()
    content_digests = {}

    for version_dir in version_dirs:
        try:
            version_inventory = self.get_version_inventory(version_dir)
            for item, digest in version_inventory.items():
                if item in root_inventory and root_inventory[item] != digest:
                    content_digests[item] = digest
                elif item not in root_inventory:
                    content_digests[item] = digest
        except FileNotFoundError:
            if self.logger:
                self.logger.warning(f"Inventory not found for version {version_dir}.")
        except Exception as e:
            if self.logger:
                self.logger.error(f"An error occurred while processing version {version_dir}: {e}")

    return content_digests

