def parse_inventory(self, inventory_lines):
    inventory = {}
    for line in inventory_lines:
        parts = line.strip().split()
        if len(parts) != 2:
            raise ValueError("Malformed inventory line: " + line)
        inventory[parts[0]] = parts[1]
    return inventory

def log_mismatch(self, item, expected_digest, actual_digest):
    print(f"Mismatch for {item}: expected {expected_digest}, got {actual_digest}")

