            merged_sub_dict = dict(merged_dict[key_value][1].value)
            for sub_key, sub_value in value.value:
                sub_key_value = sub_key.value
                if sub_key_value in merged_sub_dict:
                    if isinstance(sub_value, ruamel.yaml.nodes.MappingNode) and isinstance(merged_sub_dict[sub_key_value], ruamel.yaml.nodes.MappingNode):
                        merged_sub_dict[sub_key_value] = deep_merge_nodes([(sub_key, sub_value), (sub_key, merged_sub_dict[sub_key_value])])[0][1]
