                        merged_sub_dict[sub_key_value] = sub_value
                else:
                    merged_sub_dict[sub_key_value] = sub_value
            merged_dict[key_value][1].value = list(merged_sub_dict.items())
        else:
            # For non-MappingNode, the last one wins
            merged_dict[key_value] = (key, value)

