def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    parsed_arguments = {}
    remaining_arguments = list(unparsed_arguments)

    for subparser_name, parser in subparsers.items():
        try:
            namespace, remaining = parser.parse_known_args(unparsed_arguments)
            parsed_arguments[subparser_name] = namespace
            remaining_arguments = [arg for arg in remaining_arguments if arg not in remaining]
        except Exception as e:
            # Handle any exceptions that occur during parsing
            print(f"Error parsing arguments for subparser {subparser_name}: {e}")
            continue

    return parsed_arguments, remaining_arguments

def deep_merge_nodes(nodes):
    '''Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    from collections import defaultdict

    def merge(mapping_nodes):
        merged_mapping = defaultdict(list)
        for key, value in mapping_nodes:
            if isinstance(value, ruamel.yaml.nodes.MappingNode):
                existing = next((v for k, v in merged_mapping[key] if isinstance(v, ruamel.yaml.nodes.MappingNode)), None)
                if existing:
                    merged_value = merge(value.value + existing.value)
                    merged_mapping[key] = [(key, ruamel.yaml.nodes.MappingNode(tag=value.tag, value=list(merged_value.items())))]
                else:
                    merged_mapping[key].append((key, merge(value.value)))
            else:
                merged_mapping[key] = [(key, value)]
        return [item for items in merged_mapping.values() for item in items]

    merged_nodes = {}
    for key, value in nodes:
        if key.value in merged_nodes:
            if isinstance(value, ruamel.yaml.nodes.MappingNode) and isinstance(merged_nodes[key.value][1], ruamel.yaml.nodes.MappingNode):
                merged_value = merge(merged_nodes[key.value][1].value + value.value)
                merged_nodes[key.value] = (key, ruamel.yaml.nodes.MappingNode(tag=value.tag, value=merged_value))
            else:
                merged_nodes[key.value] = (key, value)
        else:
            merged_nodes[key.value] = (key, value)

    return list(merged_nodes.values())

