                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    from ruamel.yaml.nodes import MappingNode
    from collections import defaultdict

    def merge_mapping(existing_value, new_value):
        existing_dict = dict(existing_value.value)
        new_dict = dict(new_value.value)
        for key, val in new_dict.items():
            if key in existing_dict:
                if isinstance(existing_dict[key], MappingNode) and isinstance(val, MappingNode):
                    merge_mapping(existing_dict[key], val)
                else:
                    existing_dict[key] = val
            else:
                existing_dict[key] = val
        existing_value.value = list(existing_dict.items())

    merged_nodes = defaultdict(lambda: None)
    for key_node, value_node in nodes:
        key = key_node.value
        if key in merged_nodes:
            if isinstance(merged_nodes[key], MappingNode) and isinstance(value_node, MappingNode):
                merge_mapping(merged_nodes[key], value_node)
            else:
                merged_nodes[key] = value_node
        else:
            merged_nodes[key] = value_node

    return [(key_node, value_node) for key_node, value_node in nodes if merged_nodes[key_node.value] == value_node]

