    merged_dict = {}

    for key, value in nodes:
        key_value = key.value

        if key_value not in merged_dict:
            merged_dict[key_value] = (key, value)
        else:
            _, existing_value = merged_dict[key_value]

            if isinstance(value, MappingNode) and isinstance(existing_value, MappingNode):
                new_value = list(existing_value.value)  # Start with a copy of the existing mappings
                new_value_dict = {item[0].value: item for item in new_value}

                for k, v in value.value:
                    new_value_dict[k.value] = (k, v)

                new_value = list(new_value_dict.values())
                merged_dict[key_value] = (key, MappingNode(value.tag, new_value))
            else:
                merged_dict[key_value] = (key, value)

    return list(merged_dict.values())

