def bash_completion():
    '''
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    '''
    try:
        import argparse
        import borgmatic.commands.command
    except ImportError:
        print("borgmatic or required modules are not installed.")
        return

    parser = borgmatic.commands.command.parsers()

    def format_option(option):
        if isinstance(option, argparse._StoreAction):
            if option.const is not None:
                return f"--{option.dest}"
            elif option.nargs == 0:
                return f"--{option.dest}"
            else:
                return f"--{option.dest}=<value>"
        elif isinstance(option, argparse._StoreConstAction):
            return f"--{option.dest}"
        elif isinstance(option, argparse._StoreTrueAction):
            return f"--{option.dest}"
        elif isinstance(option, argparse._StoreFalseAction):
            return f"--{option.dest}"
        return ""

    completion_script = "#!/bin/bash\n\n_borgmatic_completion() {\n    local cur prev opts\n    COMPREPLY=()\n    cur=\"${COMP_WORDS[COMP_CWORD]}\"\n    prev=\"${COMP_WORDS[COMP_CWORD-1]}\"\n    opts=\""

    for action in parser._actions:
        completion_script += format_option(action) + " "

    completion_script += "\"\n\n    if [[ ${cur} == -* ]]; then\n        COMPREPLY=( $(compgen -W \"${opts}\" -- ${cur}) )\n        return 0\n    fi\n}\n\ncomplete -F _borgmatic_completion borgmatic\n"

    return completion_script

