    borgmatic's command-line argument parsers.
    '''
    try:
        import borgmatic.commands.arguments
        import borgmatic.commands.subparsers
        parser = borgmatic.commands.arguments.create_argument_parser()
        script = parser.format_help() + '\n'

        # Generate completion options
        for subparser in parser._subparsers._actions:
            for choice, subcommand in subparser.choices.items():
                script += f'complete -c borgmatic -s {choice} -d "{subcommand.description}"\n'
                for action in subcommand._actions:
                    if action.option_strings:
                        for opt in action.option_strings:
                            script += f'complete -c borgmatic -s {action.dest} -o {opt} -d "{action.help}"\n'
        return script
    except ImportError:
        return "borgmatic module not found. Please install borgmatic to use this feature."
    except Exception as e:
        return f"An error occurred while generating bash completion: {e}"

def parse_arguments(*unparsed_arguments):
    '''Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    '''
    import argparse

    parser = argparse.ArgumentParser()
    subparsers = parser.add_subparsers(dest='subparser_name')

    # Example subparsers, these should be defined according to your script's needs
    # parser_foo = subparsers.add_parser('foo')
    # parser_bar = subparsers.add_parser('bar')

    try:
        args = parser.parse_args(unparsed_arguments)
    except SystemExit:
        return {}

    result = {'global': args}

    # If subparsers are used, add their namespace to the result
    if args.subparser_name:
        result[args.subparser_name] = args

    return result

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    parsed_arguments = {}
    remaining_arguments = list(unparsed_arguments)

    for subparser_name, parser in subparsers.items():
        try:
            namespace, rest = parser.parse_known_args(remaining_arguments)
            parsed_arguments[subparser_name] = namespace
            remaining_arguments = rest
        except Exception as e:
            # Handle exceptions if parsing fails for a subparser
            # This could log the error or handle it as needed
            parsed_arguments[subparser_name] = None

    return parsed_arguments, remaining_arguments

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.strip()
    try:
        if size[-1].isdigit():
            return int(size)
        else:
            suffix = size[-1].upper()
            quantity = int(size[:-1])
            if suffix == 'K':
                return quantity * 1000
            elif suffix == 'M':
                return quantity * 1000**2
            elif suffix == 'G':
                return quantity * 1000**3
            elif suffix == 'T':
                return quantity * 1000**4
            else:
                raise ValueError(f"Unrecognized suffix: {suffix}")
    except (ValueError, IndexError) as e:
        raise ValueError(f"Invalid size format: {size}") from e

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.strip()
    if not size:
        raise ValueError("Size cannot be empty")

    try:
        # Try to convert to direct integer
        return int(size)
    except ValueError:
        # Not an integer, check for suffixes
        suffixes = {
            'K': 1000,
            'M': 1_000_000,
            'G': 1_000_000_000,
            'T': 1_000_000_000_000,
        }

        suffix = size[-1].upper()
        if suffix in suffixes:
            try:
                value = int(size[:-1])
                return value * suffixes[suffix]
            except ValueError:
                raise ValueError(f"Invalid size format: {size}")
        else:
            raise ValueError(f"Unknown suffix: {suffix}")

