def regex_dict(item):
    """Convert *.cpp keys to regex keys

    Given a dict where the keys are all filenames with wildcards, convert only
    the keys into equivalent regexes and leave the values intact.

    Example:

    rules = {
        '*.cpp':
            {'a': 'arf', 'b': 'bark', 'c': 'coo'},
        '*.h':
            {'h': 'help'}
    }
    regex_keys = regex_dict(rules)

    Args:
        item: dict to convert
    Returns:
        dict with keys converted to regexes
    """
    regex_converted = {}
    for key, value in item.items():
        if key.endswith('*.cpp'):
            regex_key = re.escape(key[:-4]) + r'[^/]*\.cpp'
        elif key.endswith('*.h'):
            regex_key = re.escape(key[:-2]) + r'[^/]*\.h'
        else:
            regex_key = re.escape(key)
        regex_converted[regex_key] = value
    return regex_converted

def regex_dict(item):
    """
    Convert *.cpp keys to regex keys

    Given a dict where the keys are all filenames with wildcards, convert only
    the keys into equivalent regexes and leave the values intact.

    Example:

    rules = {
        '*.cpp':
            {'a': 'arf', 'b': 'bark', 'c': 'coo'},
        '*.h':
            {'h': 'help'}
    }
    regex_keys = regex_dict(rules)

    Args:
        item: dict to convert
    Returns:
        dict with keys converted to regexes
    """
    if not isinstance(item, dict):
        raise ValueError("The input must be a dictionary.")

    regex_patterns = {
        r'\*': r'.*',
        r'\?': r'.'
    }

    def wildcard_to_regex(pattern):
        for wildcard, regex in regex_patterns.items():
            pattern = re.sub(re.escape(wildcard), regex, pattern)
        return pattern + r'$'

    return {wildcard_to_regex(key): value for key, value in item.items()}

