def _resolve_string(matcher):
    '''Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    if '=' in matcher:
        name, default = matcher.split('=', 1)
    else:
        name, default = matcher, None

    value = os.getenv(name, default)
    if value is None:
        raise ValueError(f"Environment variable {name} is not set and no default value is provided.")

    return value

def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    if isinstance(matcher, tuple) and len(matcher) == 2:
        name, default = matcher
    elif isinstance(matcher, str):
        name = matcher
        default = None
    else:
        raise ValueError("Matcher must be a string or a tuple of (string, default_value)")

    value = os.getenv(name)
    if value is None:
        if default is not None:
            return default
        else:
            raise EnvironmentError(f"Environment variable '{name}' is not set and no default value is provided.")
    return value

