def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    mu = 0.2
    sigma = 0.1
    try:
        return (1 / (sigma * np.sqrt(2 * np.pi))) * np.exp(-0.5 * ((x - mu) / sigma) ** 2)
    except Exception as e:
        raise ValueError(f"An error occurred while calculating the Gaussian: {e}")

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging
    import configparser
    import os

    config_dict = {}
    log_records = []

    for filename in config_filenames:
        config = configparser.ConfigParser()
        try:
            with open(filename, 'r') as config_file:
                config.read_file(config_file)
            if overrides:
                for section, settings in overrides.items():
                    if not config.has_section(section):
                        config.add_section(section)
                    for key, value in settings.items():
                        config.set(section, key, value)
            if resolve_env:
                for section in config.sections():
                    for key, value in config.items(section):
                        config.set(section, key, os.path.expandvars(value))
            config_dict[filename] = {section: dict(config.items(section)) for section in config.sections()}
        except (configparser.Error, IOError) as e:
            log_record = logging.LogRecord(
                name='ConfigLoader',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=str(e),
                args=(),
                exc_info=True
            )
            log_records.append(log_record)

    return config_dict, log_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging
    import configparser
    import os

    config_dict = {}
    log_records = []

    if overrides is None:
        overrides = {}

    for config_filename in config_filenames:
        try:
            config = configparser.ConfigParser()
            if resolve_env:
                config.read(os.path.expandvars(config_filename))
            else:
                config.read(config_filename)

            # Apply overrides
            for section, options in overrides.items():
                if section not in config:
                    config[section] = {}
                for key, value in options.items():
                    if value is not None:
                        config[section][key] = value
                    else:
                        config[section].pop(key, None)

            config_dict[config_filename] = config
        except Exception as e:
            log_record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname='config_loader.py',
                lineno=0,
                msg=f'Error reading configuration file {config_filename}: {e}',
                args=(),
                exc_info=True
            )
            log_records.append(log_record)

    return config_dict, log_records

