def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    if other is None:
        if self._scale is None:
            raise ValueError("Graph scale is not set")
        return self._scale
    else:
        if not isinstance(other, (int, float)):
            raise TypeError("Scale must be a numeric value")
        if self._scale is None or self._scale == 0:
            raise ValueError("Cannot rescale a graph with unknown or zero scale")
        factor = other / self._scale
        self._scale = other
        try:
            for point in self.points:
                point[-1] *= factor
                if point.errors is not None:
                    point.errors[-1] *= factor
        except AttributeError:
            raise ValueError("Graph does not have points to rescale")

def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    if other is None:
        if self._scale is None or self._scale == 0:
            raise LenaValueError("Graph has unknown or zero scale")
        return self._scale
    else:
        if self._scale is None or self._scale == 0:
            raise LenaValueError("Graph has unknown or zero scale, cannot rescale")
        try:
            other = float(other)
        except ValueError:
            raise TypeError("Scale must be a numeric value")

        scale_factor = other / self._scale
        self._scale = other
        if hasattr(self, '_last_coordinate'):
            self._last_coordinate *= scale_factor
        if hasattr(self, 'errors'):
            for i in range(len(self.errors)):
                self.errors[i] *= scale_factor

def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
    interface using ``iface.providedBy`` (unless *tentative* is `True`,
    in which case this step is skipped). This means that the candidate's class
    declares that it `implements <zope.interface.implementer>` the interface,
    or the candidate itself declares that it `provides <zope.interface.provider>`
    the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
    extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    from zope.interface.exceptions import Invalid
    from zope.interface.verify import verifyObject as zope_verifyObject, verifyClass

    errors = []

    if not tentative:
        if not iface.providedBy(candidate):
            errors.append(f"Candidate does not claim to provide the interface {iface}")

    for name in iface.names():
        if callable(iface[name]):
            if not hasattr(candidate, name):
                errors.append(f"Candidate does not define method: {name}")
            else:
                method = getattr(candidate, name)
                if not callable(method):
                    errors.append(f"Candidate attribute {name} is not callable")
        else:
            if not hasattr(candidate, name):
                errors.append(f"Candidate does not define attribute: {name}")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("Errors found:\n" + "\n".join(errors))

    # Use zope's verifyObject to check method signatures and more
    try:
        zope_verifyObject(iface, candidate)
    except Invalid as e:
        errors.append(str(e))

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("Errors found:\n" + "\n".join(errors))

    return True

def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
    interface using ``iface.providedBy`` (unless *tentative* is `True`,
    in which case this step is skipped). This means that the candidate's class
    declares that it `implements <zope.interface.implementer>` the interface,
    or the candidate itself declares that it `provides <zope.interface.provider>`
    the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
    extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    from zope.interface.exceptions import Invalid
    errors = []

    if not tentative:
        if not iface.providedBy(candidate):
            errors.append(f"Candidate does not provide the interface {iface.__name__}")

    for name in iface.names(True):
        if name not in candidate.__dict__ and name not in dir(candidate):
            errors.append(f"Missing attribute or method '{name}'")

    for attr in iface.names(True):
        if iface.getAttribute(attr).isRequired():
            try:
                getattr(candidate, attr)
            except AttributeError:
                errors.append(f"Required attribute or method '{attr}' not found")

    for method_name in iface.names(True):
        method = iface.getAttribute(method_name)
        if not callable(method):
            continue

        try:
            candidate_method = getattr(candidate, method_name)
        except AttributeError:
            continue

        if not callable(candidate_method):
            errors.append(f"Attribute '{method_name}' is not callable (should be a method)")
            continue

        # Get the signature of the method from the interface and the candidate
        from inspect import signature
        try:
            iface_method_sig = signature(method)
        except ValueError:
            # Some built-in methods do not have a signature, we can't check these
            continue

        try:
            candidate_method_sig = signature(candidate_method)
        except Exception as e:
            errors.append(f"Error obtaining signature for method '{method_name}': {str(e)}")
            continue

        # Compare the bindability of the signatures
        iface_params = iface_method_sig.parameters
        candidate_params = candidate_method_sig.parameters

        for param_name in iface_params:
            iface_param = iface_params[param_name]
            if param_name not in candidate_params:
                errors.append(f"Method '{method_name}' is missing parameter '{param_name}'")
                continue

            candidate_param = candidate_params[param_name]

            if iface_param.annotation is not iface_param.empty and candidate_param.annotation is not iface_param.annotation:
                errors.append(f"Method '{method_name}' parameter '{param_name}' has incorrect annotation (expected {iface_param.annotation}, got {candidate_param.annotation})")

            if iface_param.default is iface_param.empty and candidate_param.default is not iface_param.empty:
                errors.append(f"Method '{method_name}' parameter '{param_name}' cannot have a default value")

            if iface_param.kind != candidate_param.kind:
                errors.append(f"Method '{method_name}' parameter '{param_name}' has incorrect kind (expected {iface_param.kind}, got {candidate_param.kind})")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("Multiple errors:\n" + "\n".join(errors))

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    try:
        if isinstance(candidate, iface):
            return True
        elif tentative:
            return issubclass(candidate, iface)
        else:
            return False
    except TypeError:
        return False

