    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    try:
        if tentative:
            return all(hasattr(candidate, attr) for attr in iface.__abstractmethods__)
        else:
            return issubclass(candidate, iface) and not isinstance(candidate, iface)
    except TypeError:
