def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc

    metas = set()
    for base in bases:
        metas.add(type(base))
        metas.update(getattr(base, '__mro__', []))

    if len(metas) == 1:
        return metas.pop()

    for meta in metas:
        if issubclass(meta, metas):
            return meta

    raise TypeError("Metaclass conflict: the metaclasses %s are incompatible"
                    " with each other" % ','.join(map(str, metas)))

