def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    import re
    tags = set()
    code_block = False
    lines = text.split('\n')
    result_lines = []

    for line in lines:
        if line.strip().startswith('```'):
            code_block = not code_block
        if not code_block:
            tag_pattern = r'#(\w+)\b'
            if replacer:
                def replace_func(match):
                    tag = match.group(1)
                    tags.add(tag)
                    return '#' + replacer(tag)
                new_line = re.sub(tag_pattern, replace_func, line)
            else:
                new_line = line
                for match in re.finditer(tag_pattern, line):
                    tag = match.group(1)
                    tags.add(tag)
            result_lines.append(new_line)
        else:
            result_lines.append(line)

    return tags, '\n'.join(result_lines)

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    import re

    def linkify(match):
        url = match.group(0)
        return f'<a href="{url}" target="_blank" rel="noopener noreferrer">{url}</a>'

    if not isinstance(text, str):
        raise ValueError("Input must be a string")

    # Regular expression for URLs
    url_pattern = re.compile(
        r'http[s]?://'  # http:// or https://
        r'(?:(?:[a-zA-Z]|[0-9]|[$-_@.&+]|[!*\\(\\),]|'  # domain...
        r'(?:%[0-9a-fA-F][0-9a-fA-F]))+'  # ...name
    )

    try:
        processed_text = url_pattern.sub(linkify, text)
    except re.error as e:
        raise ValueError(f"Regex error: {e}")

    return processed_text

